import React from 'react';
import type { SVMParams } from '../types';
import { Copy, Check } from 'lucide-react';

interface CodeGeneratorProps {
  params: SVMParams;
  template: string;
}

function generatePythonCode(params: SVMParams): string {
  const kernelMap = {
    linear: 'linear',
    polynomial: 'poly',
    rbf: 'rbf',
  };

  return `# ─── SVM Classification with Scikit-Learn ────────────────────────
# Auto-generated by HyperPlane Studio
# Parameters synced from your interactive simulation

import numpy as np
import matplotlib.pyplot as plt
from sklearn.svm import SVC
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score, classification_report
from sklearn.preprocessing import StandardScaler

# ─── 1. Generate or load your dataset ─────────────────────────────
# Replace this with your actual data
from sklearn.datasets import make_classification
X, y = make_classification(
    n_samples=200,
    n_features=2,
    n_informative=2,
    n_redundant=0,
    n_clusters_per_class=1,
    random_state=42
)

# ─── 2. Preprocessing ─────────────────────────────────────────────
scaler = StandardScaler()
X_scaled = scaler.fit_transform(X)
X_train, X_test, y_train, y_test = train_test_split(
    X_scaled, y, test_size=0.2, random_state=42
)

# ─── 3. Create and train the SVM model ────────────────────────────
model = SVC(
    kernel='${kernelMap[params.kernelType]}',
    C=${params.C.toFixed(4)},${params.kernelType === 'rbf' ? `
    gamma=${params.gamma.toFixed(4)},` : ''}${params.kernelType === 'polynomial' ? `
    degree=${params.degree},
    gamma=${params.gamma.toFixed(4)},
    coef0=${params.coef0.toFixed(1)},` : ''}
    random_state=42
)
model.fit(X_train, y_train)

# ─── 4. Evaluate ──────────────────────────────────────────────────
y_pred = model.predict(X_test)
accuracy = accuracy_score(y_test, y_pred)
print(f"Accuracy: {accuracy:.4f}")
print(f"Support Vectors: {model.n_support_}")
print(f"\\nClassification Report:\\n{classification_report(y_test, y_pred)}")

# ─── 5. Visualize decision boundary ──────────────────────────────
fig, ax = plt.subplots(1, 1, figsize=(10, 8))

# Create mesh grid
h = 0.02
x_min, x_max = X_scaled[:, 0].min() - 1, X_scaled[:, 0].max() + 1
y_min, y_max = X_scaled[:, 1].min() - 1, X_scaled[:, 1].max() + 1
xx, yy = np.meshgrid(np.arange(x_min, x_max, h),
                      np.arange(y_min, y_max, h))

# Decision function values
Z = model.decision_function(np.c_[xx.ravel(), yy.ravel()])
Z = Z.reshape(xx.shape)

# Plot decision boundary and margins
ax.contourf(xx, yy, Z, levels=50, cmap='RdBu', alpha=0.3)
ax.contour(xx, yy, Z, levels=[0], colors='#10b981', linewidths=2.5)
ax.contour(xx, yy, Z, levels=[-1, 1], colors='#10b981',
           linewidths=1.5, linestyles='dashed')

# Plot data points
scatter = ax.scatter(X_scaled[:, 0], X_scaled[:, 1],
                     c=y, cmap='RdBu', edgecolors='white',
                     s=50, linewidths=0.5)

# Highlight support vectors
ax.scatter(model.support_vectors_[:, 0],
           model.support_vectors_[:, 1],
           s=200, facecolors='none', edgecolors='#f59e0b',
           linewidths=2, label='Support Vectors')

ax.set_xlabel('Feature 1')
ax.set_ylabel('Feature 2')
ax.set_title('SVM Decision Boundary (kernel=${kernelMap[params.kernelType]}, C=${params.C.toFixed(2)})')
ax.legend()
plt.tight_layout()
plt.show()`;
}

export default function CodeGenerator({ params, template }: CodeGeneratorProps) {
  const [copied, setCopied] = React.useState(false);
  const code = generatePythonCode(params);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback
      const textarea = document.createElement('textarea');
      textarea.value = code;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  // Simple syntax highlighting
  const highlightCode = (code: string): React.ReactNode[] => {
    return code.split('\n').map((line, i) => {
      let highlighted = line;

      // Comments
      if (line.trimStart().startsWith('#')) {
        return (
          <div key={i} className="code-comment">
            {line}
          </div>
        );
      }

      // Process the line for syntax highlighting
      const parts: React.ReactNode[] = [];
      const tokens = line.split(
        /((?:from|import|as|def|class|return|if|else|for|in|print|True|False|None)\b|'[^']*'|"[^"]*"|f"[^"]*"|\d+\.?\d*)/g
      );

      tokens.forEach((token, ti) => {
        if (/^(from|import|as)$/.test(token)) {
          parts.push(<span key={ti} className="code-import">{token}</span>);
        } else if (/^(def|class|return|if|else|for|in)$/.test(token)) {
          parts.push(<span key={ti} className="code-keyword">{token}</span>);
        } else if (/^(print|True|False|None)$/.test(token)) {
          parts.push(<span key={ti} className="code-function">{token}</span>);
        } else if (/^['"]/.test(token) || /^f"/.test(token)) {
          parts.push(<span key={ti} className="code-string">{token}</span>);
        } else if (/^\d+\.?\d*$/.test(token)) {
          parts.push(<span key={ti} className="code-number">{token}</span>);
        } else {
          parts.push(<span key={ti}>{token}</span>);
        }
      });

      return <div key={i}>{parts}</div>;
    });
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="glass-card overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-border">
          <div className="flex items-center gap-3">
            <div className="flex gap-1.5">
              <div className="w-3 h-3 rounded-full bg-accent-rose/60" />
              <div className="w-3 h-3 rounded-full bg-accent-amber/60" />
              <div className="w-3 h-3 rounded-full bg-accent-emerald/60" />
            </div>
            <span className="text-xs font-mono text-txt-muted">svm_experiment.py</span>
          </div>
          <button
            onClick={handleCopy}
            className="btn-ghost flex items-center gap-1.5 text-xs"
          >
            {copied ? (
              <>
                <Check className="w-3.5 h-3.5 text-accent-emerald" />
                <span className="text-accent-emerald">Copied!</span>
              </>
            ) : (
              <>
                <Copy className="w-3.5 h-3.5" />
                <span>Copy</span>
              </>
            )}
          </button>
        </div>

        {/* Code */}
        <div className="code-block rounded-none border-0 max-h-[600px] overflow-y-auto">
          <pre className="text-xs leading-relaxed">
            {highlightCode(code)}
          </pre>
        </div>

        {/* Footer info */}
        <div className="px-5 py-3 border-t border-border bg-canvas-primary/30">
          <p className="text-[10px] text-txt-muted">
            This code is auto-generated based on your current simulation parameters.
            Adjust C, γ, kernel type in the Simulation tab and the code updates automatically.
          </p>
        </div>
      </div>
    </div>
  );
}
